mapper.select:
SELECT people_id, meal_date AS day, 0 AS minutes
FROM diet_meal
WHERE tenant_id = #{tenantId}
  AND people_id IN
  #{pid}
  AND meal_date >= #{from}
  AND meal_date <= #{to}
  AND is_deleted = 0
GROUP BY people_id, meal_date

SELECT people_id, exercise_date AS day, COALESCE(SUM(active_min), 0) AS minutes
FROM exercise_session
WHERE tenant_id = #{tenantId}
  AND people_id IN
  #{pid}
  AND exercise_date >= #{from}
  AND exercise_date <= #{to}
  AND is_deleted = 0
GROUP BY people_id, exercise_date
